PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "axes_accessattempt" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "get_data" text NOT NULL, "post_data" text NOT NULL, "failures_since_start" integer unsigned NOT NULL CHECK ("failures_since_start" >= 0));
CREATE TABLE IF NOT EXISTS "axes_accessfailurelog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "locked_out" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "axes_accesslog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_agent" varchar(255) NOT NULL, "ip_address" char(39) NULL, "username" varchar(255) NULL, "http_accept" varchar(1025) NOT NULL, "path_info" varchar(255) NOT NULL, "attempt_time" datetime NOT NULL, "logout_time" datetime NULL, "session_hash" varchar(64) NOT NULL);
CREATE TABLE IF NOT EXISTS "axes_accessattemptexpiration" ("access_attempt_id" integer NOT NULL PRIMARY KEY REFERENCES "axes_accessattempt" ("id") DEFERRABLE INITIALLY DEFERRED, "expires_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "duty_department" ("code" varchar(8) NOT NULL PRIMARY KEY, "name" varchar(32) NOT NULL UNIQUE, "shifts" varchar(64) NOT NULL);
CREATE TABLE IF NOT EXISTS "duty_department_managers" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "department_id" varchar(8) NOT NULL REFERENCES "duty_department" ("code") DEFERRABLE INITIALLY DEFERRED, "member_id" bigint NOT NULL REFERENCES "duty_member" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "duty_changelog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "at" datetime NOT NULL, "date" date NOT NULL, "cell" varchar(8) NOT NULL, "by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "after_id" bigint NULL REFERENCES "duty_member" ("id") DEFERRABLE INITIALLY DEFERRED, "before_id" bigint NULL REFERENCES "duty_member" ("id") DEFERRABLE INITIALLY DEFERRED, "period_id" bigint NOT NULL REFERENCES "duty_period" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "changelog_cell_valid" CHECK ("cell" IN ('dawn', 'normal', 'dinner', 'slot0', 'slot1', 'slot2', 'slot3', 'slot4', 'slot5', 'slot6', 'slot7', 'slot8', 'slot9', 'night')), CONSTRAINT "changelog_not_empty" CHECK (("before_id" IS NOT NULL OR "after_id" IS NOT NULL)));
CREATE TABLE IF NOT EXISTS "duty_commute" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "shift" varchar(8) NOT NULL, "member_id" bigint NOT NULL REFERENCES "duty_member" ("id") DEFERRABLE INITIALLY DEFERRED, "period_id" bigint NOT NULL REFERENCES "duty_period" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "commute_one_shift_per_day" UNIQUE ("period_id", "date", "member_id"), CONSTRAINT "commute_shift_valid" CHECK ("shift" IN ('dawn', 'normal', 'dinner', 'night')));
CREATE TABLE IF NOT EXISTS "duty_controlduty" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "slot" smallint unsigned NOT NULL CHECK ("slot" >= 0), "member_id" bigint NOT NULL REFERENCES "duty_member" ("id") DEFERRABLE INITIALLY DEFERRED, "period_id" bigint NOT NULL REFERENCES "duty_period" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "duty_one_member_per_slot" UNIQUE ("period_id", "date", "slot"), CONSTRAINT "duty_slot_range" CHECK ("slot" < 10));
CREATE TABLE IF NOT EXISTS "duty_member" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(16) NOT NULL UNIQUE, "name" varchar(32) NOT NULL UNIQUE, "part" varchar(32) NOT NULL, "type" varchar(8) NOT NULL, "is_active" bool NOT NULL, "must_change_password" bool NOT NULL, "department_id" varchar(8) NOT NULL REFERENCES "duty_department" ("code") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "member_type_valid" CHECK ("type" IN ('직원', '개발자')));
CREATE TABLE IF NOT EXISTS "duty_period" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(64) NOT NULL, "start_date" date NOT NULL, "end_date" date NOT NULL, "status" varchar(16) NOT NULL, "seed" bigint NULL, "generated_at" datetime NULL, "published_at" datetime NULL, "overwrite_from" date NULL, CONSTRAINT "period_status_valid" CHECK ("status" IN ('draft', 'collecting', 'closed', 'generated', 'published')), CONSTRAINT "period_dates_ordered" CHECK ("start_date" <= ("end_date")));
CREATE TABLE IF NOT EXISTS "duty_rosterpref" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "depts" text NOT NULL CHECK ((JSON_VALID("depts") OR "depts" IS NULL)), "types" text NOT NULL CHECK ((JSON_VALID("types") OR "types" IS NULL)), "shifts" text NOT NULL CHECK ((JSON_VALID("shifts") OR "shifts" IS NULL)), "view" varchar(5) NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "rosterpref_view_valid" CHECK ("view" IN ('week', 'month')));
CREATE TABLE IF NOT EXISTS "duty_pushalarmsubscription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "endpoint" varchar(500) NOT NULL UNIQUE, "p256dh" varchar(200) NOT NULL, "auth" varchar(100) NOT NULL, "label" varchar(80) NOT NULL, "created_at" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "duty_alarmrule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "enabled" bool NOT NULL, "kind" varchar(8) NOT NULL, "timing" varchar(12) NOT NULL, "offset" integer NOT NULL, "at_minute" integer NOT NULL, "telegram" bool NOT NULL, "push" bool NOT NULL, "shifts" text NOT NULL CHECK ((JSON_VALID("shifts") OR "shifts" IS NULL)), "depts" text NOT NULL CHECK ((JSON_VALID("depts") OR "depts" IS NULL)), "types" text NOT NULL CHECK ((JSON_VALID("types") OR "types" IS NULL)), "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "alarmrule_kind_valid" CHECK ("kind" IN ('personal', 'report')), CONSTRAINT "alarmrule_timing_valid" CHECK ("timing" IN ('before_start', 'days', 'bizdays')), CONSTRAINT "alarmrule_offset_range" CHECK ((("offset" >= 1 AND "offset" <= 10080 AND "timing" = 'before_start') OR ("offset" >= 0 AND "offset" <= 30 AND "timing" = 'days') OR ("offset" >= 1 AND "offset" <= 30 AND "timing" = 'bizdays'))), CONSTRAINT "alarmrule_at_minute_range" CHECK (("at_minute" >= 0 AND "at_minute" <= 1439)), CONSTRAINT "alarmrule_before_start_no_time" CHECK ((NOT ("timing" = 'before_start') OR "at_minute" = 0)), CONSTRAINT "alarmrule_has_channel" CHECK (("telegram" OR "push")), CONSTRAINT "alarmrule_personal_no_filters" CHECK (("kind" = 'report' OR ("depts" = '[]' AND "types" = '[]'))), CONSTRAINT "alarmrule_unique" UNIQUE ("user_id", "kind", "timing", "offset", "at_minute", "shifts", "depts", "types"));
CREATE TABLE IF NOT EXISTS "duty_alarmdelivery" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "cell" varchar(8) NOT NULL, "channel" varchar(8) NOT NULL, "destination" varchar(64) NOT NULL, "status" varchar(8) NOT NULL, "attempts" integer NOT NULL, "next_attempt_at" datetime NULL, "content_hash" varchar(64) NOT NULL, "last_sent_hash" varchar(64) NULL, "updated_at" datetime NOT NULL, "rule_id" bigint NOT NULL REFERENCES "duty_alarmrule" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "alarmdelivery_channel_valid" CHECK ("channel" IN ('telegram', 'push')), CONSTRAINT "alarmdelivery_cell_valid" CHECK ("cell" IN ('dawn', 'normal', 'dinner', 'slot0', 'slot1', 'slot2', 'slot3', 'slot4', 'slot5', 'slot6', 'slot7', 'slot8', 'slot9', 'night', 'report')), CONSTRAINT "alarmdelivery_status_valid" CHECK ("status" IN ('sent', 'failed')), CONSTRAINT "alarmdelivery_attempts_nonneg" CHECK ("attempts" >= 0), CONSTRAINT "alarmdelivery_once" UNIQUE ("rule_id", "date", "cell", "channel", "destination"));
CREATE TABLE IF NOT EXISTS "duty_telegramalarmprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "chat_id" varchar(32) NOT NULL, "verified_at" datetime NULL, "last_test_at" datetime NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "link_code" varchar(32) NULL UNIQUE, "link_expires_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "duty_calendarfeed" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token_hash" varchar(64) NOT NULL UNIQUE, "issued_at" datetime NOT NULL, "user_id" integer NOT NULL UNIQUE REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
